pub struct RoleFindManyBuilder<'a, E> {
    executor: E,
    where_input: &'a crate::firms::RoleWhereInput,
    order_by: Vec<crate::firms::RoleOrderByWithRelationInput>,
    take: Option<i64>,
    skip: Option<i64>,
}

impl<'a, E> RoleFindManyBuilder<'a, E> {
    pub fn order_by(mut self, order_by: &[crate::firms::RoleOrderByWithRelationInput]) -> Self {
        self.order_by = order_by.to_vec();
        self
    }

    pub fn take(mut self, n: i64) -> Self {
        self.take = Some(n);
        self
    }

    pub fn skip(mut self, n: i64) -> Self {
        self.skip = Some(n);
        self
    }

    pub async fn exec<'e>(self) -> sqlx::Result<Vec<crate::firms::Role>>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        let mut qb =
            sqlx::QueryBuilder::new(r#"SELECT "id", "role_name" FROM "rb_user_roles" WHERE "#);
        if !crate::engine::sqlx_postgres::firms::push_role_where(&mut qb, self.where_input) {
            qb.push("TRUE");
        }
        if !self.order_by.is_empty() {
            qb.push(" ORDER BY ");
            let mut first = true;
            for ob in &self.order_by {
                if let Some(o) = ob.id {
                    if !first {
                        qb.push(", ");
                    }
                    first = false;
                    qb.push("\"id\" ");
                    qb.push(crate::engine::sqlx_postgres::filters::sort_order_sql(o));
                }
                if let Some(o) = ob.role_name {
                    if !first {
                        qb.push(", ");
                    }
                    first = false;
                    qb.push("\"role_name\" ");
                    qb.push(crate::engine::sqlx_postgres::filters::sort_order_sql(o));
                }
            }
        }
        if let Some(n) = self.take {
            qb.push(" LIMIT ");
            qb.push_bind(n);
        }
        if let Some(n) = self.skip {
            qb.push(" OFFSET ");
            qb.push_bind(n);
        }
        qb.build_query_as::<crate::firms::Role>()
            .fetch_all(self.executor)
            .await
    }
}

